
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_df3_opt2_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_df3_opt2", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.243272487192557e+00, -4.160589298603641e+00, -4.044793389808980e+00, -3.884521184147774e+00, -3.666416203128747e+00, -3.376754041730503e+00, -3.005284605406499e+00, -2.552212452563093e+00, -2.037763847084416e+00, -1.507493837385582e+00, -1.014983132262986e+00, -6.938038639867288e-01, -5.966117027747436e-01, -4.889978018031842e-01, -3.521826755510557e-01, -2.243843207411447e-01, -1.266469991749011e-01, -5.611636012526867e-02, -1.750684613002829e-02, -3.757902670558596e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


